/**
 * The skill-tool entity's sub-type table. Skill tools are a real sub-entity —
 * six terraform resource types sharing one ownership shape (skill_id +
 * name/description/status) — so per-sub-type knowledge is one ROW here,
 * exactly like `entities/agent-tool/types.ts` (which this mirrors).
 *
 * Search-table support stays coupled to the underlying AI search-table graph
 * module; every other provider skill-tool resource is implemented end to end.
 *
 * Note the wire key for the automation tool is `automation`, not agent-tool's
 * `executeWorkflow` — confirmed against the live provider schema
 * (`entities/skill/tools.ts`'s `skillAutomation` factory).
 */
export const SKILL_TOOL_SUB_TYPES = [
    { typeKey: "createRecord", resourceType: "elementum_agentic_skill_create_record_tool", implemented: true },
    { typeKey: "searchAspect", resourceType: "elementum_agentic_skill_search_records_tool", implemented: true },
    { typeKey: "updateRecord", resourceType: "elementum_agentic_skill_update_record_tool", implemented: true },
    { typeKey: "searchTable", resourceType: "elementum_agentic_skill_ai_search_tool", implemented: true },
    { typeKey: "runAgent", resourceType: "elementum_agentic_skill_run_agent_tool", implemented: true },
    { typeKey: "automation", resourceType: "elementum_agentic_skill_run_automation_tool", implemented: true },
];
export const SKILL_TOOL_SUB_TYPE_BY_TYPE_KEY = new Map(SKILL_TOOL_SUB_TYPES.map((t) => [t.typeKey, t]));
export const SKILL_TOOL_SUB_TYPE_BY_RESOURCE = new Map(SKILL_TOOL_SUB_TYPES.map((t) => [t.resourceType, t]));
/** The resource types the terraform path round-trips today (adoption scope). */
export const IMPLEMENTED_SKILL_TOOL_RESOURCE_TYPES = SKILL_TOOL_SUB_TYPES.filter((t) => t.implemented === true).map((t) => t.resourceType);
/** Every declared skill-tool resource type — stream partition recognizes these by name. */
export const ALL_SKILL_TOOL_RESOURCE_TYPES = SKILL_TOOL_SUB_TYPES.map((t) => t.resourceType);
